def roman_to_int(s):
    """
    Converts a Roman numeral string to an integer.

    Args:
        s (str): A string of Roman numerals.

    Returns:
        int: The integer equivalent of the Roman numeral string.

    Raises:
        ValueError: If the input string contains invalid Roman numerals.
    """
    roman_numerals = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }

    result = 0
    for i in range(len(s)):
        if i > 0 and roman_numerals[s[i]] > roman_numerals[s[i - 1]]:
            result += roman_numerals[s[i]] - 2 * roman_numerals[s[i - 1]]
        else:
            result += roman_numerals[s[i]]

    return result

def flatten(nested):
    flat_list = []
    for item in nested:
        if isinstance(item, list):
            flat_list.extend(flatten(item))
        else:
            flat_list.append(item)
    return flat_list

from collections import defaultdict

def group_anagrams(words):
    if not words:
        return []

    anagrams = defaultdict(list)
    for word in words:
        sorted_word = "".join(sorted(word))
        anagrams[sorted_word].append(word)

    groups = sorted(anagrams.values(), key=lambda x: x[0])
    return [sorted(group) for group in groups]

def longest_common_prefix(strs):
    if not strs:
        return ""

    shortest_str = min(strs, key=len)

    for i, char in enumerate(shortest_str):
        for other in strs:
            if other[i] != char:
                return shortest_str[:i]

    return shortest_str

def is_valid_ipv4(s):
    parts = s.split('.')
    return len(parts) == 4 and all(part.isdigit() and 0 <= int(part) <= 255 for part in parts)

def median(nums):
    """Return the median of a non-empty list of numbers."""
    s = sorted(nums)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    else:
        return (s[n // 2 - 1] + s[n // 2]) / 2

def chunk(items, size):
    """Split items into lists of length size. The last list may be shorter."""
    return [items[i:i + size] for i in range(0, len(items), size)]

def is_sorted(nums, reverse=False):
    """True if nums is sorted ascending (or descending if reverse=True).
    Equal neighbours are allowed."""
    for a, b in zip(nums, nums[1:]):
        if reverse:
            if a > b:
                return False
        else:
            if a <= b:
                return False
    return True

def fib(n, memo={}):
    """Return the n-th Fibonacci number, with fib(0) = 0 and fib(1) = 1."""
    if n < 2:
        return n
    elif n in memo:
        return memo[n]
    else:
        result = fib(n - 1, memo) + fib(n - 2, memo)
        memo[n] = result
        return result

def average(nums):
    """Return the mean of a list of numbers, ignoring None values and rounding to 2 decimal places."""
    nums = [num for num in nums if num is not None]
    if not nums:
        return None
    return round(sum(nums) / len(nums), 2)
